// دالة أمان: تتفادى الخطأ إيلا node مازال ماخدمش (0 items وصلاتو)
function safeGetAll(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return []; // النود ماخدمش = ماكانش محتوى من هاد النوع فهاد الدفعة
  }
}
const textItems  = safeGetAll('Text');
const audioItems = safeGetAll('Groq-STT');
const imageItems = safeGetAll('Analyze image');
const videoItems = safeGetAll('Analyze video');
const postItems  = safeGetAll('Build Post Summary');
const reelItems  = safeGetAll('Build Reel Summary');
const senderId = $('Extract Sender ID').item.json.senderId;

function safe(val) {
  if (val === null || val === undefined) return null;
  const s = String(val).trim();
  return s.length > 0 ? s : null;
}

const texts = textItems
  .map(item => safe(item.json.Text || item.json.text))
  .filter(Boolean);
const audios = audioItems
  .map(item => safe(item.json.text || item.json.Text))
  .filter(Boolean);
const images = imageItems
  .map(item => safe(
    item.json?.choices?.[0]?.message?.content ||
    item.json.Text || item.json.text
  ))
  .filter(Boolean);
const videos = videoItems
  .map(item => safe(
    item.json?.choices?.[0]?.message?.content ||
    item.json.Text || item.json.text
  ))
  .filter(Boolean);
const posts = postItems
  .map(item => safe(item.json.Text))
  .filter(Boolean);
const reels = reelItems
  .map(item => safe(item.json.Text))
  .filter(Boolean);

const sections = [];
if (texts.length > 0) {
  sections.push(
    `📝 رسائل نصية (${texts.length}):\n` +
    texts.map((t, i) => texts.length > 1 ? `${i + 1}. ${t}` : t).join('\n')
  );
}
if (audios.length > 0) {
  sections.push(
    `🎤 تفريغ رسائل صوتية (${audios.length}):\n` +
    audios.map((t, i) => audios.length > 1 ? `${i + 1}. ${t}` : t).join('\n')
  );
}
if (images.length > 0) {
  sections.push(
    `🖼️ وصف صور مرسلة (${images.length}):\n` +
    images.map((t, i) => `صورة ${i + 1}:\n${t}`).join('\n\n')
  );
}
if (videos.length > 0) {
  sections.push(
    `🎬 وصف فيديوهات مرسلة (${videos.length}):\n` +
    videos.map((t, i) => `فيديو ${i + 1}:\n${t}`).join('\n\n')
  );
}
if (posts.length > 0) {
  sections.push(
    `🔗 منشورات مشاركة (${posts.length}):\n` +
    posts.map((t, i) => posts.length > 1 ? `منشور ${i + 1}:\n${t}` : t).join('\n\n')
  );
}
if (reels.length > 0) {
  sections.push(
    `🎥 ريلز مشاركة (${reels.length}):\n` +
    reels.map((t, i) => reels.length > 1 ? `ريل ${i + 1}:\n${t}` : t).join('\n\n')
  );
}

const receivedTypes = [];
if (texts.length)  receivedTypes.push('نص');
if (audios.length) receivedTypes.push('رسائل صوتية');
if (images.length) receivedTypes.push('صور');
if (videos.length) receivedTypes.push('فيديوهات');
if (posts.length)  receivedTypes.push('منشور مُشارك');
if (reels.length)  receivedTypes.push('ريل مُشارك');

const header = receivedTypes.length > 0
  ? `📥 المحتوى المستلم من المستخدم في هذه الدفعة: ${receivedTypes.join('، ')}\n`
  : '';

const body = sections.length > 0
  ? sections.join('\n\n---\n\n')
  : '(لم يصل أي محتوى قابل للفهم من المستخدم في هذه الدفعة)';

const finalContext = header ? `${header}\n${body}` : body;

return [{
  json: {
    finalContext,
    senderId,
    meta: {
      hasText: texts.length > 0,
      hasAudio: audios.length > 0,
      hasImage: images.length > 0,
      hasVideo: videos.length > 0,
      hasPost: posts.length > 0,
      hasReel: reels.length > 0,
      totalContentPieces: texts.length + audios.length + images.length + videos.length + posts.length + reels.length
    }
  }
}];

const item = $input.first().json;
const rawUrl = item.payload?.url || "";

// 1. استخراج story_fbid عبر Regex
const storyMatch = rawUrl.match(/story_fbid=([^&]+)/);
const storyFbid = storyMatch ? storyMatch[1] : "";

// 2. استخراج id الخاص بالصفحة عبر Regex
const pageMatch = rawUrl.match(/[?&]id=([^&]+)/);
const pageId = pageMatch ? pageMatch[1] : "";

// 3. تركيب المعرّف المركّب المطلوبة لـ Graph API: {PageID}_{PostID}
let finalId = "";
if (pageId && storyFbid) {
  finalId = `${pageId}_${storyFbid}`;
} else if (storyFbid) {
  finalId = storyFbid;
} else {
  finalId = item.payload?.id;
}

return [{
  json: {
    ...item,
    graphPostId: finalId
  }
}];

// 1. جلب الكابشن والرابط من الـ Webhook و HTTP Request
const webhookData = $('Split Out').first()?.json?.payload || {};
const postDetails = $('Get Post Details').first()?.json || {};

const postTitle = webhookData.title || postDetails.message || "بدون نص";
const postUrl = webhookData.url || "";

// 2. جلب نتيجة تحليل الصورة إن وجدت (فقط الصورة، الفيديو ماعادش من مسؤولية هاد الـ branch)
let mediaAnalysis = "";

try {
  const imgAnalysis = $('Analyze Post Image').first()?.json?.choices?.[0]?.message?.content;
  if (imgAnalysis) mediaAnalysis += `\n🖼️ [وصف صورة المنشور]: ${imgAnalysis}`;
} catch (e) {}

// 3. صياغة النص النهائي الموحد
const fullPostSummary = `🔗 منشور مشارك من العميل:\n- النص/الكابشن: ${postTitle}${mediaAnalysis}\n- رابط المنشور: ${postUrl}`;

return [{
  json: {
    Text: fullPostSummary
  }
}];

