// خطوة 1: دالة أمان — تتفادى error إيلا node ماخدمش هاد الدورة
function safeGetAll(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return []; // النود ماخدمش = ماكانش محتوى من هاد النوع
  }
}

// خطوة 2: دالة تنضيف — كتشيل قيم فارغة/null
function safe(val) {
  if (val === null || val === undefined) return null;
  const s = String(val).trim();
  return s.length > 0 ? s : null;
}

// خطوة 3: نجمعو الـ items من كل فرع محتمل
const textItems  = safeGetAll('Echo Text');
const audioItems = safeGetAll('Echo Groq-STT');
const imageItems = safeGetAll('Echo Analyze Image');
const videoItems = safeGetAll('Echo Analyze Video');

// خطوة 4: نجيبو senderId من العقدة اللي استخرجاتو (ماشي من $json الحالي)
const senderId = $('Extract Customer ID from Echo').item.json.senderId;

// خطوة 5: نسحبو النص من الحقل الصحيح حسب نوع كل فرع
const texts = textItems
  .map(item => safe(item.json.Text))
  .filter(Boolean);

const audios = audioItems
  .map(item => safe(item.json.text))
  .filter(Boolean);

const images = imageItems
  .map(item => safe(item.json?.choices?.[0]?.message?.content))
  .filter(Boolean);

const videos = videoItems
  .map(item => safe(item.json?.choices?.[0]?.message?.content))
  .filter(Boolean);

// خطوة 6: نبنيو الأقسام - غير الفرع اللي فيه بيانات حقيقية
const sections = [];
if (texts.length)  sections.push(`💬 نص:\n${texts.join('\n')}`);
if (audios.length) sections.push(`🎤 تفريغ ملاحظة صوتية:\n${audios.join('\n')}`);
if (images.length) sections.push(`🖼️ وصف صورة مرسلة:\n${images.join('\n\n')}`);
if (videos.length) sections.push(`🎬 وصف فيديو مرسل:\n${videos.join('\n\n')}`);

// خطوة 7: fallback إيلا نوع مرفق غير مدعوم (sticker, file...)
const body = sections.length > 0
  ? sections.join('\n\n')
  : '(نوع محتوى غير مدعوم حاليًا - لم يتم استخراج نص منه)';

// خطوة 8: الرسالة النهائية
const EchoMessage = `📩 رد صاحب المتجر يدويًا عبر Messenger:\n${body}`;

return [{
  json: {
    EchoMessage,
    senderId
  }
}];
